#include <stdio.h>

void my_strcpy(char *dest, const char *src) {
    int i = 0;
    while (src[i] != '\0') {
        dest[i] = src[i];
        i++;
    }
    dest[i] = '\0';
}

void my_strcat(char *dest, const char *src) {
    int end = 0;
    while (dest[end] != '\0') {
        end++;
    }
    my_strcpy(dest + end, src);
}

int main() {
    char buffer[50];
    my_strcpy(buffer, "Code");
    my_strcat(buffer, "Varsity");
    printf("%s\n", buffer);
    return 0;
}
